  const lab = "block text-xs font-semibold uppercase tracking-wider text-white/70 mb-1.5";
  const set = (k) => (ev) => setSeo({ ...seo, [k]: ev.target.value });
  const mt = seo.metaTitle || title || "", md = seo.metaDescription || excerpt || "";
